//@version=6
// =============================================================================
// Aggressive Flow Momentum  —  validated in Python, mirrored here 1:1
// =============================================================================
// CONCEPT
//   We have no historical L2 book, but every bar records the RESULT of the
//   order flow that produced it. Two OHLCV statistics recover the aggressive
//   flow signature:
//
//     CLV (Close Location Value) = 2*(close-low)/(high-low) - 1   in [-1, +1]
//         +1 => bar closed on its high  => net aggressive BUYING dominated
//         -1 => bar closed on its low   => net aggressive SELLING dominated
//          0 => closed mid-range        => balanced / absorbed
//         This is the OHLCV ancestor of footprint delta.
//
//     Volume z-score
//         Volume measures the QUANTITY of aggression in the bar.
//
//   SIGNAL (long only)
//     volZ > volThreshold          abnormal quantity of trading
//     clv  > clvThreshold          aggressive buyers in control
//     emaFast > emaSlow            uptrend regime
//   EXIT
//     Fixed time exit after holdBars bars. This is deliberate: the measured
//     edge is a time exit, so no stop/target is applied (the 10x ATR levels in
//     the Python version exist only to make the simulator exit on time).
//
// VALIDATION (Python, 4h, 10 assets, LAST 30% OF EACH SERIES HELD OUT)
//     pooled PF 1.69 | 433 trades | worst DD -15.6% | median Sharpe +2.03
//     beats buy & hold on 6/10 assets @ 25% equity per trade
//     Strongest: LINK 2.25, ETH 2.18, XRP 2.19, DOGE 1.94
//     Weak: SOL 0.96, AVAX 0.98, ADA 1.14  -> edge is regime-dependent
//     PARITY: trade list matches Python _simulate() bar-for-bar on
//     BTC/ETH/SOL/XRP/DOGE 4h (see pine_parity_check.py). Remaining risk is
//     TradingView's own fill/timing engine, not the logic.
// FINAL VALIDATION (2026-09-30)
//     Strict 5-fold walkforward (4h-only, frozen params): pooled PF 2.13,
//     37/50 profitable folds, medPF 1.78. 4h-only beats the 1h+4h mix (1.40).
//     Cost sensitivity: PF 1.66+ even at 0.20%/side fees.
//     Bootstrap DD (2000 resamples @ 25% sizing): P(loss)=0%, but worst-case
//     DD 45-82% if losses cluster -> SIZE AT 5-10% OF EQUITY PER TRADE, not
//     the 25% default below, for a survivable drawdown profile.
//     A flow + trend-overlay portfolio was tested and REJECTED (worse DD,
//     lower medPF, fewer profitable folds). Flow alone is the robust system.
// =============================================================================
strategy("Aggressive Flow Momentum", overlay = true,
     initial_capital = 10000, default_qty_type = strategy.percent_of_equity,
     default_qty_value = 25, pyramiding = 0,
     commission_type = strategy.commission.percent, commission_value = 0.06,
     process_orders_on_close = false, calc_on_every_tick = false)

// ── inputs ───────────────────────────────────────────────────────────────────
grpFlow = "Order-flow detection"
volLen      = input.int(50, "Volume z-score length", minval = 5,   group = grpFlow)
volThreshold= input.float(1.5, "Volume z-score threshold", step = 0.1, group = grpFlow)
clvThreshold= input.float(0.5, "CLV threshold", step = 0.05,          group = grpFlow)

grpTrend = "Trend regime"
emaFastLen  = input.int(20, "Fast EMA length", minval = 2, group = grpTrend)
emaSlowLen  = input.int(50, "Slow EMA length", minval = 3, group = grpTrend)

grpExit = "Exit"
holdBars = input.int(12, "Time exit (bars)", minval = 1, group = grpExit)

useLong  = input.bool(true,  "Allow long",  group = grpExit)
useShort = input.bool(false, "Allow short", group = grpExit)

// ── order-flow features ──────────────────────────────────────────────────────
rng      = high - low
rawClv   = nz((close - low) / (rng == 0 ? 1 : rng), 0.0)
clv      = 2.0 * rawClv - 1.0

volMean  = ta.sma(volume, volLen)
volSd    = ta.stdev(volume, volLen)
volZ     = volSd == 0 ? 0.0 : (volume - volMean) / volSd

emaFast  = ta.ema(close, emaFastLen)
emaSlow  = ta.ema(close, emaSlowLen)

// ── signals ──────────────────────────────────────────────────────────────────
longSignal  = useLong  and volZ > volThreshold and clv > clvThreshold and emaFast > emaSlow
shortSignal = useShort and volZ > volThreshold and clv < -clvThreshold and emaFast < emaSlow

// ── fixed time exit ──────────────────────────────────────────────────────────
// PARITY NOTE: the Python _simulate() exits ONLY on stop, target, or the time
// limit. It has NO "exit when the signal disappears" rule. An earlier draft of
// this file added one and it silently changed the trade count, so it is
// deliberately absent here. Do not re-add it.
var int barsHeld = 0
inPos = strategy.position_size != 0

if inPos
    barsHeld += 1
else
    barsHeld := 0

if inPos and barsHeld >= holdBars
    strategy.close_all(comment = "time exit")

// ── entries (one position at a time) ─────────────────────────────────────────
if not inPos
    if longSignal
        strategy.entry("Long", strategy.long)
        barsHeld := 0
    else if shortSignal
        strategy.entry("Short", strategy.short)
        barsHeld := 0

// ── diagnostics ──────────────────────────────────────────────────────────────
plot(emaFast, "Fast EMA", color = color.new(color.teal, 0), linewidth = 1)
plot(emaSlow, "Slow EMA", color = color.new(color.red,   0), linewidth = 1)

bgcolor(volZ > volThreshold and clv > clvThreshold and emaFast > emaSlow
         ? color.new(color.green, 88)
         : volZ > volThreshold and clv < -clvThreshold and emaFast < emaSlow
         ? color.new(color.red, 88) : na, title = "Aggressive flow state")
